<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { descargarFirmado, listarFirma, prepararFirma } from '../services/firma'
import type { DocumentoFirma } from '../interfaces/firma.interface'
import type { CatalogOption } from '../../interfaces/documento'
const criterio=ref(''),estado=ref(''),items=ref<DocumentoFirma[]>([]),instancia=ref<CatalogOption|null>(null),habilitada=ref(false),pagination=reactive({current:1,last:1,total:0}),loading=ref(false),processing=ref(0),error=ref(''),success=ref(''),selected=ref<DocumentoFirma|null>(null),options=reactive({signatureReason:1,signatureStyle:1,stampTextSize:12})
async function load(page=1){loading.value=true;error.value='';try{const r=await listarFirma(criterio.value,estado.value,page);items.value=r.data;habilitada.value=r.firma_habilitada;instancia.value=r.instancia||null;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cargar la bandeja de firma.'}finally{loading.value=false}}
async function sign(){if(!selected.value)return;processing.value=selected.value.id;error.value='';try{const r=await prepararFirma(selected.value.id,{...options});success.value=r.message||'Parámetros de firma preparados. Se abrirá ReFirma.';selected.value=null;if(r.launch_url)window.location.href=r.launch_url}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo iniciar ReFirma. Verifica que ReFirma Invoker esté instalado y en ejecución.'}finally{processing.value=0}}
async function download(i:DocumentoFirma){processing.value=i.id;try{await descargarFirmado(i.id)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo descargar.'}finally{processing.value=0}}
function number(i:DocumentoFirma){return i.numero||`Documento #${i.id}`}
function date(v?:string|null){return v?new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
function state(i:DocumentoFirma){return i.firmado_digitalmente?'Firmado':i.estado_firma==='error'?'Error':i.estado_firma==='pendiente'?'Pendiente':'Listo para firmar'}
onMounted(()=>load())
</script>
<template><div class="signature"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Reportes y firma / Firma digital</nav><header class="hero"><div class="mark">FD</div><div><small>Firma digital RENIEC</small><h1>Bandeja de firma</h1><p>Firma documentos PDF mediante ReFirma Invoker y descarga los archivos resultantes.</p></div><aside v-if="instancia"><b>{{instancia.nombre}}</b><span>{{habilitada?'Firma habilitada':'Firma no habilitada'}}</span></aside><strong>{{pagination.total}} documentos</strong></header><div v-if="!habilitada&&!loading" class="warning"><b>Firma digital no disponible</b><span>La instancia activa no tiene habilitado el requisito de firma digital.</span></div><div v-if="success" class="flash">✓ {{success}}</div><div v-if="error" class="flash error">{{error}}</div><form class="filters" @submit.prevent="load()"><label><span>Número o asunto</span><input v-model.trim="criterio" placeholder="Buscar documento"></label><label><span>Estado de firma</span><select v-model="estado"><option value="">Todos</option><option value="listo">Listo para firmar</option><option value="pendiente">Pendiente</option><option value="firmado">Firmado</option><option value="error">Con error</option></select></label><button>Buscar</button><button type="button" class="clear" @click="criterio='';estado='';load()">Limpiar</button></form><div v-if="loading" class="notice">Cargando documentos para firma…</div><div v-else-if="!items.length" class="notice"><b>No hay documentos en la bandeja</b><span>Los documentos de tipo proveído no requieren firma digital.</span></div><section v-else class="cards"><article v-for="i in items" :key="i.id" :class="{signed:i.firmado_digitalmente,failed:i.estado_firma==='error'}"><header><div class="pdf">PDF</div><div><small>{{i.tipo_documento?.nombre||'Documento'}} · #{{i.id}}</small><h2>{{number(i)}}</h2></div><span>{{state(i)}}</span></header><div class="body"><h3>{{i.asunto}}</h3><dl><div><dt>Archivo</dt><dd>{{i.archivo||'No cargado'}}</dd></div><div><dt>Registro</dt><dd>{{date(i.created_at)}}</dd></div><div v-if="i.firmado_digitalmente"><dt>Fecha de firma</dt><dd>{{date(i.fecha_firma)}}</dd></div><div v-if="i.certificado_firmante"><dt>Certificado</dt><dd>{{i.certificado_firmante}}</dd></div></dl></div><footer><button v-if="i.firmado_digitalmente&&i.archivo_firmado" :disabled="processing===i.id" class="download" @click="download(i)">Descargar firmado</button><button v-else :disabled="!habilitada||!i.archivo||processing===i.id" @click="selected=i">{{i.estado_firma==='error'?'Reintentar firma':'Firmar documento'}}</button></footer></article></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="load(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="load(pagination.current+1)">Siguiente</button></footer><div v-if="selected" class="backdrop" @mousedown.self="selected=null"><section class="modal"><header><div><small>Preparar firma digital</small><h2>{{number(selected)}}</h2></div><button @click="selected=null">×</button></header><form @submit.prevent="sign"><div class="requirements"><b>Antes de continuar</b><span>Comprueba que ReFirma Invoker esté instalado, abierto y que el certificado digital se encuentre disponible.</span></div><label><span>Motivo de la firma</span><select v-model="options.signatureReason"><option :value="1">Soy el autor del documento</option><option :value="2">En señal de conformidad</option><option :value="3">Doy V°B°</option><option :value="4">Por encargo</option><option :value="5">Doy fe</option><option :value="6">Autenticación de documento digitalizado</option></select></label><label><span>Estilo visible</span><select v-model="options.signatureStyle"><option :value="1">Estampado y descripción horizontal</option><option :value="2">Estampado y descripción vertical</option><option :value="3">Solo estampado</option><option :value="4">Solo descripción</option><option :value="0">Firma invisible</option></select></label><label><span>Tamaño del texto del sello</span><input v-model.number="options.stampTextSize" type="number" min="8" max="20"></label><footer><button type="button" class="clear" @click="selected=null">Cancelar</button><button :disabled="processing!==0">{{processing?'Preparando…':'Abrir ReFirma y firmar'}}</button></footer></form></section></div></div></template>
<style scoped>
