r{display:flex;justify-content:flex-end;gap:7px}@media(max-width:950px){.cards{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}}@media(max-width:620px){.hero{flex-wrap:wrap}.hero aside{width:100%;margin:0;text-align:left}.cards,.filters{grid-template-columns:1fr}.warning{display:block}.warning span{display:block;margin-top:4px}}
